from __future__ import annotations

PRO_CONTROL_UI = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>TITAN · Channel Intelligence</title>
<style>
:root{color-scheme:dark;--bg:#07090a;--panel:#111518;--panel2:#151b1f;--line:#283137;--text:#edf2f3;--muted:#87939a;--green:#62f2b5;--amber:#f2b84b;--red:#ff6b6b;--blue:#79aaff;font-family:Inter,Segoe UI,system-ui,sans-serif}*{box-sizing:border-box}body{margin:0;background:#07090a;color:var(--text)}button,input,select{font:inherit}.wrap{max-width:1600px;margin:auto;padding:22px}.top,.row,.head{display:flex;gap:12px;align-items:center;justify-content:space-between}.top{align-items:flex-start}.eyebrow{color:var(--green);font-size:11px;font-weight:800;letter-spacing:.18em}h1{margin:4px 0;font-size:27px}h2{margin:0;font-size:16px}.muted{color:var(--muted);font-size:12px}.pills,.toolbar{display:flex;gap:8px;flex-wrap:wrap}.pill,.badge{border:1px solid var(--line);border-radius:999px;padding:6px 9px;font-size:10px}.ok{color:var(--green);border-color:#285e48}.wait{color:var(--amber);border-color:#6b5225}.bad{color:var(--red);border-color:#6d2c2c}.card{background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:14px}.toolbar{margin:14px 0}.btn{border:1px solid var(--line);background:#1b2226;color:#fff;border-radius:7px;padding:9px 12px;font-weight:700;cursor:pointer}.btn.primary{background:var(--green);color:#06110c;border-color:transparent}.btn.amber{background:var(--amber);color:#171005;border-color:transparent}.btn.danger{background:#39191b;color:#ffb1b1}.btn:disabled{opacity:.45;cursor:not-allowed}.tempo{width:82px;background:#0b0f11;border:1px solid var(--line);color:#fff;border-radius:7px;padding:9px}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-top:14px}.metric b{display:block;font-size:18px;margin-top:5px}.section{margin-top:22px}.tracks{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.track{background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:14px}.track.active{border-color:#315f4d}.titleline{display:flex;align-items:flex-start;gap:10px}.trackname{font-weight:850;font-size:15px}.role{margin-left:auto;background:#0b0f11;border:1px solid var(--line);color:#fff;border-radius:6px;padding:6px}.device{margin-top:10px;background:#0c1012;border:1px solid #20282d;border-radius:8px;padding:10px}.device-head{display:flex;gap:8px;align-items:center;justify-content:space-between}.device-name{font-weight:750}.paramgrid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px;margin-top:8px}.param{font-size:10px;color:#b4bec3;border-top:1px solid #1e262b;padding-top:6px}.param span{color:var(--muted)}.macros{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:7px;margin-top:10px}.macro{background:#12181b;border:1px solid #253038;border-radius:7px;padding:8px}.macro label{display:flex;justify-content:space-between;font-size:10px;color:#b8c2c7}.macro input{width:100%;accent-color:var(--green)}.bindings{font-size:9px;color:var(--muted);min-height:28px;margin-top:4px}.mixrow{display:grid;grid-template-columns:1fr 1fr auto;gap:8px;margin-top:10px}.mixrow input{width:100%;accent-color:var(--blue)}.log{display:flex;flex-direction:column;gap:6px}.event{display:grid;grid-template-columns:110px 1fr auto;gap:10px;background:#0d1113;border:1px solid #20282d;border-radius:7px;padding:8px;font-size:10px}.error{color:var(--red);font-size:12px;margin-top:8px}.notice{border-left:3px solid var(--amber);background:#19150c;padding:10px 12px;color:#d8c48e;font-size:11px;margin-top:10px}.empty{padding:30px;text-align:center;color:var(--muted);border:1px dashed var(--line);border-radius:10px}@media(max-width:1000px){.tracks{grid-template-columns:1fr}.metrics{grid-template-columns:repeat(2,1fr)}}@media(max-width:620px){.wrap{padding:14px}.top{flex-direction:column}.metrics,.paramgrid,.macros{grid-template-columns:1fr}.mixrow{grid-template-columns:1fr}}
</style></head><body><main class="wrap">
<header class="top"><div><div class="eyebrow">TITAN · CHANNEL INTELLIGENCE</div><h1>Live 11 Production Console</h1><div class="muted">Real track/device discovery · exact parameter readback · semantic controls only on discovered parameters</div></div><div class="pills"><span id="bridgePill" class="pill wait">BRIDGE</span><span id="receiverPill" class="pill wait">ABLETON</span><span id="discoveryPill" class="pill wait">DISCOVERY</span></div></header>
<section class="metrics"><div class="card metric"><span class="muted">Live tempo</span><b id="tempoMetric">—</b></div><div class="card metric"><span class="muted">Tracks</span><b id="trackMetric">—</b></div><div class="card metric"><span class="muted">Devices</span><b id="deviceMetric">—</b></div><div class="card metric"><span class="muted">Bound controls</span><b id="bindingMetric">—</b></div></section>
<div class="toolbar"><button class="btn primary" onclick="discover()">DISCOVER LIVE SET</button><button class="btn" onclick="simple('start_playback')">PLAY</button><button class="btn" onclick="simple('stop_playback')">STOP</button><input id="tempoInput" class="tempo" type="number" min="20" max="300" value="134"><button class="btn" onclick="setTempo()">SET TEMPO</button><button class="btn amber" onclick="captureAll()">SNAPSHOT DEVICES</button><button class="btn" onclick="loadHistory()">REFRESH LOG</button></div>
<div id="error" class="error"></div>
<div class="notice">Safety: parameter controls are generated only after Live returns exact device and parameter names. Every semantic change is clamped to normalized 0–1 and uses the exact name returned by Live. Low-confidence mappings are displayed but never auto-applied.</div>
<section class="section"><div class="head"><div><h2>Live Tracks</h2><div class="muted">Mixer state, device chain, parameter inventory and semantic channel controls.</div></div></div><div id="tracks" class="tracks"><div class="empty">Press DISCOVER LIVE SET with Ableton Live 11 open and the Receiver loaded.</div></div></section>
<section class="section"><div class="head"><div><h2>Command / ACK Log</h2><div class="muted">Runtime evidence from the local bridge.</div></div></div><div id="log" class="log"></div></section>
</main><script>
const token=localStorage.bridgeToken||new URLSearchParams(location.search).get('token')||'';if(new URLSearchParams(location.search).get('token')){localStorage.bridgeToken=token;history.replaceState({},'',location.pathname)}
const headers=()=>({'Content-Type':'application/json','X-Bridge-Token':token});
let live={tracks:[],returns:[],state:null};let busy=false;let commandLog=[];
const clamp=x=>Math.max(0,Math.min(1,x));const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function setError(v=''){document.querySelector('#error').textContent=v}
function setBusy(v){busy=v;document.querySelectorAll('button').forEach(b=>b.disabled=v)}
async function submit(payload){const r=await fetch('/command',{method:'POST',headers:headers(),body:JSON.stringify(payload)});const d=await r.json();if(!r.ok)throw Error(d.error||'Bridge command failed');return d.command}
async function waitAck(c,timeout=7000){const until=Date.now()+timeout;while(Date.now()<until){const r=await fetch('/api/commands/'+c.id,{headers:headers()});const d=await r.json();if(!r.ok)throw Error(d.error||'ACK read failed');const x=d.command;if(x.status==='acknowledged'||x.status==='simulated')return x;if(x.status==='error'||x.status==='rejected')throw Error(x.error||x.command_type+' failed');await new Promise(q=>setTimeout(q,100))}throw Error('No Ableton ACK for '+c.command_type)}
async function exec(payload){return waitAck(await submit(payload))}
async function simple(type,extra={}){try{setBusy(true);setError();await exec({type,...extra});await loadHistory()}catch(e){setError(e.message)}finally{setBusy(false)}}
async function setTempo(){await simple('set_tempo',{bpm:Number(document.querySelector('#tempoInput').value)})}
function inferRole(name){const n=name.toLowerCase();if(n.includes('kick'))return'kick';if(n.includes('bass')||n.includes('reese'))return'bass';if(n.includes('hat'))return'hats';if(n.includes('snare')||n.includes('clap')||n.includes('perc')||n.includes('drum'))return'drums';if(n.includes('seq')||n.includes('lead')||n.includes('melody')||n.includes('synth')||n.includes('stab'))return'sequence';if(n.includes('pad')||n.includes('ambient')||n.includes('atmo'))return'atmosphere';if(n.includes('fx')||n.includes('riser')||n.includes('impact'))return'fx';if(n.includes('voice')||n.includes('vocal'))return'voice';return'other'}
const macroProfiles={
 kick:{punch:['attack','transient','punch'],body:['body','tone','boom'],tail:['decay','release','tail'],drive:['drive','saturat','distort']},
 bass:{body:['body','osc','sub','tone'],bite:['cutoff','filter freq','frequency','brightness'],movement:['lfo amount','mod amount','modulation'],release:['release','decay']},
 hats:{brightness:['cutoff','filter freq','brightness','tone'],decay:['decay','release'],air:['air','high','treble'],drive:['drive','saturat','distort']},
 drums:{punch:['attack','transient','punch'],snap:['snap','click','tone'],decay:['decay','release'],drive:['drive','saturat','distort']},
 sequence:{motion:['lfo amount','mod amount','modulation'],tension:['resonance','res','feedback'],tone:['cutoff','filter freq','brightness','tone'],space:['dry/wet','reverb','delay','echo']},
 atmosphere:{motion:['lfo amount','mod amount','modulation'],width:['width','stereo'],tone:['cutoff','filter freq','brightness','tone'],space:['dry/wet','reverb','delay','echo']},
 fx:{motion:['rate','modulation','lfo amount'],tone:['cutoff','filter freq','tone'],feedback:['feedback'],space:['dry/wet','reverb','delay','echo']},
 voice:{presence:['cutoff','filter freq','presence','tone'],air:['air','high','treble'],space:['dry/wet','reverb','delay'],drive:['drive','saturat']},
 other:{tone:['cutoff','filter freq','tone'],movement:['lfo amount','mod amount'],space:['dry/wet','reverb','delay'],drive:['drive','saturat','distort']}
};
function scoreParam(name,aliases){const n=name.toLowerCase();let best=0;for(const a of aliases){if(n===a)best=Math.max(best,1);else if(n.includes(a))best=Math.max(best,a.length>=6?.9:.75)}return best}
function buildBindings(track){const profile=macroProfiles[track.role]||macroProfiles.other;const out={};for(const [macro,aliases] of Object.entries(profile)){const candidates=[];for(const d of track.deviceDetails||[]){for(const p of d.parameters||[]){if(p.is_quantized)continue;const confidence=scoreParam(p.name,aliases);if(confidence>=.75)candidates.push({device:d.device,param:p.name,current:p.normalized,confidence})}}candidates.sort((a,b)=>b.confidence-a.confidence);out[macro]=candidates.slice(0,2)}return out}
async function discover(){try{setBusy(true);setError();const state=(await exec({type:'get_live_state'})).result||{};const tracks=(await exec({type:'list_tracks'})).result?.tracks||[];live.state=state;live.tracks=[];for(const t of tracks){const track={...t,role:inferRole(t.name),deviceDetails:[]};const chain=(await exec({type:'inspect_device_chain',target_kind:'track',track_name:t.name})).result||{};track.device_chain=chain.devices||[];for(const d of track.device_chain){const detail=(await exec({type:'inspect_device_parameters',target_kind:'track',track_name:t.name,device:d.name})).result||{};track.deviceDetails.push(detail)}track.bindings=buildBindings(track);live.tracks.push(track)}render();await loadHistory();document.querySelector('#discoveryPill').className='pill ok';document.querySelector('#discoveryPill').textContent='DISCOVERED'}catch(e){setError(e.message);document.querySelector('#discoveryPill').className='pill bad';document.querySelector('#discoveryPill').textContent='DISCOVERY ERROR'}finally{setBusy(false)}}
function changeRole(i,value){live.tracks[i].role=value;live.tracks[i].bindings=buildBindings(live.tracks[i]);render()}
function bindingText(items){if(!items.length)return'No safe binding';return items.map(x=>`${x.device} · ${x.param} · ${Math.round(x.confidence*100)}%`).join('<br>')}
function render(){const tracks=document.querySelector('#tracks');let devices=0,bindings=0;for(const t of live.tracks){devices+=t.deviceDetails.length;for(const b of Object.values(t.bindings||{}))bindings+=b.filter(x=>x.confidence>=.9).length}document.querySelector('#tempoMetric').textContent=live.state?.tempo?Number(live.state.tempo).toFixed(1):'—';document.querySelector('#trackMetric').textContent=live.tracks.length;document.querySelector('#deviceMetric').textContent=devices;document.querySelector('#bindingMetric').textContent=bindings;tracks.innerHTML=live.tracks.map((t,i)=>`<article class="track active"><div class="titleline"><div><div class="trackname">${esc(t.name)}</div><div class="muted">Track ${t.index} · ${t.deviceDetails.length} devices · vol ${Number(t.volume||0).toFixed(2)} · pan ${Number(t.pan||0).toFixed(2)}</div></div><select class="role" onchange="changeRole(${i},this.value)">${Object.keys(macroProfiles).map(r=>`<option ${r===t.role?'selected':''}>${r}</option>`).join('')}</select></div><div class="mixrow"><label class="muted">Volume<input type="range" min="0" max="1" step=".01" value="${t.volume}" onchange="setMix(${i},'volume',this.value)"></label><label class="muted">Pan<input type="range" min="-1" max="1" step=".01" value="${t.pan}" onchange="setMix(${i},'pan',this.value)"></label><button class="btn" onclick="refreshTrack(${i})">READBACK</button></div><div class="macros">${Object.entries(t.bindings||{}).map(([m,b])=>`<div class="macro"><label><span>${m.toUpperCase()}</span><span id="mv-${i}-${m}">0</span></label><input type="range" min="-.25" max=".25" step=".01" value="0" oninput="document.querySelector('#mv-${i}-${m}').textContent=(+this.value).toFixed(2)" onchange="applyMacro(${i},'${m}',+this.value);this.value=0;document.querySelector('#mv-${i}-${m}').textContent='0'"><div class="bindings">${bindingText(b)}</div></div>`).join('')}</div>${t.deviceDetails.map(d=>`<div class="device"><div class="device-head"><span class="device-name">${esc(d.device)}</span><span class="badge ok">LIVE READBACK</span></div><div class="paramgrid">${(d.parameters||[]).slice(0,12).map(p=>`<div class="param">${esc(p.name)}<br><span>${Number(p.normalized).toFixed(3)} · ${p.is_quantized?'quantized':'continuous'}</span></div>`).join('')}</div></div>`).join('')}</article>`).join('')||'<div class="empty">No tracks returned by Live.</div>'}
async function setMix(i,key,value){const t=live.tracks[i];try{setBusy(true);if(key==='volume'){await exec({type:'set_track_volume',track_name:t.name,volume:Number(value)});t.volume=Number(value)}else{await exec({type:'set_track_pan',track_name:t.name,pan:Number(value)});t.pan=Number(value)}await loadHistory()}catch(e){setError(e.message)}finally{setBusy(false)}}
async function refreshTrack(i){try{setBusy(true);const t=live.tracks[i];const detail=(await exec({type:'inspect_track',track_name:t.name})).result||{};Object.assign(t,detail);t.deviceDetails=[];for(const d of detail.device_chain||[]){const p=(await exec({type:'inspect_device_parameters',target_kind:'track',track_name:t.name,device:d.name})).result||{};t.deviceDetails.push(p)}t.bindings=buildBindings(t);render()}catch(e){setError(e.message)}finally{setBusy(false)}}
async function ensureSnapshot(track,device){track.snapshots=track.snapshots||{};if(track.snapshots[device])return track.snapshots[device];const sid='ci-'+track.index+'-'+Date.now();await exec({type:'capture_device_snapshot',target_kind:'track',track_name:track.name,device,snapshot_id:sid});track.snapshots[device]=sid;return sid}
async function applyMacro(i,macro,delta){const t=live.tracks[i],items=(t.bindings||{})[macro]||[];const safe=items.filter(x=>x.confidence>=.9);if(!safe.length){setError(`No high-confidence binding for ${t.name} / ${macro}. Nothing changed.`);return}try{setBusy(true);setError();for(const x of safe){await ensureSnapshot(t,x.device);const value=clamp(x.current+delta);await exec({type:'set_device_parameter',track_name:t.name,device:x.device,parameter:x.param,value});x.current=value}await refreshTrack(i);await loadHistory()}catch(e){setError(e.message)}finally{setBusy(false)}}
async function captureAll(){try{setBusy(true);for(const t of live.tracks)for(const d of t.deviceDetails||[])await ensureSnapshot(t,d.device);setError();await loadHistory()}catch(e){setError(e.message)}finally{setBusy(false)}}
async function loadHistory(){try{const h=await fetch('/health').then(r=>r.json());document.querySelector('#bridgePill').className='pill '+(h.ok?'ok':'bad');document.querySelector('#bridgePill').textContent=h.ok?'BRIDGE ONLINE':'BRIDGE ERROR';document.querySelector('#receiverPill').className='pill '+(h.max_receiver_seen?'ok':'wait');document.querySelector('#receiverPill').textContent=h.max_receiver_seen?'ABLETON ACK':'WAITING ABLETON';const r=await fetch('/api/commands?limit=40',{headers:headers()});const d=await r.json();if(!r.ok)throw Error(d.error);commandLog=d.commands||[];document.querySelector('#log').innerHTML=commandLog.map(c=>`<div class="event"><span>${esc(c.command_type)}</span><span>${esc(c.status)}${c.error?' · '+esc(c.error):''}</span><span>${esc((c.created_at||'').slice(11,19))}</span></div>`).join('')||'<div class="empty">No commands yet.</div>'}catch(e){setError(e.message)}}
loadHistory();setInterval(loadHistory,2500);
</script></body></html>'''
